190	    /**
191	     * The owner's member id, formatted {@code '<REGION><FY><HASH8><CHK>'} with no separators: the
192	     * region code baked from the postcode at creation, the two-digit fiscal year of the
193	     * business-day-adjusted registration date, the eight upper-hex {@code HASH8} (the first eight hex
194	     * characters of the SHA-256 digest of the normalized telephone followed by the last name, the same
195	     * segment used by the region-and-hash identity), and a single Luhn check digit {@code CHK} computed
196	     * over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW261A2B3C4D7'}). Assigned at
197	     * creation time; if the computed value collides with an existing owner's member id it is
198	     * de-duplicated by appending {@code '-<n>'}. This single value unifies the former customer code and
199	     * membership number.
200	     */
201	    public String getMemberId() {
202	        return this.memberId;
203	    }
204	
205	    public void setMemberId(String memberId) {
206	        this.memberId = memberId;
207	    }
208	
209	    /** Width of the {@code <FY>} (fiscal-year) segment of a base member id. */
210	    private static final int MEMBER_ID_FY_LENGTH = 2;
211	
212	    /** Width of the {@code <HASH8>} segment of a base member id. */
213	    private static final int MEMBER_ID_HASH8_LENGTH = 8;
214	
215	    /** Width of the {@code <CHK>} (Luhn check digit) segment of a base member id. */
216	    private static final int MEMBER_ID_CHK_LENGTH = 1;
217	
218	    /**
219	     * Width of the fixed-length tail of a base member id that follows the variable-length
220	     * {@code <REGION>}: the {@code <FY>}, {@code <HASH8>} and {@code <CHK>} segments together. The
221	     * region is everything before this tail, and the fiscal year is its first
222	     * {@link #MEMBER_ID_FY_LENGTH} characters.
223	     */
224	    private static final int MEMBER_ID_FIXED_TAIL =
225	        MEMBER_ID_FY_LENGTH + MEMBER_ID_HASH8_LENGTH + MEMBER_ID_CHK_LENGTH;
226	
227	    /**
228	     * The owner's member id with any de-duplication suffix stripped — the base
229	     * {@code '<REGION><FY><HASH8><CHK>'} value from which the region and fiscal-year segments are read.
230	     * The base carries no {@code '-'}; the collision suffix (when present) is {@code '-<n>'}, so the
231	     * base is the portion before the first {@code '-'}.
232	     */
233	    private String memberIdBase() {
234	        int dash = this.memberId.indexOf('-');
235	        return dash < 0 ? this.memberId : this.memberId.substring(0, dash);
236	    }
