294	    /**
295	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
296	     */
297	    @Transient
298	    public String getDisplayName() {
299	        return this.getLastName() + ", " + this.getFirstName();
300	    }
301	
302	    /**
303	     * The owner's salutation: the honorific {@link #getTitle() title} and the last name separated by
304	     * a single space (e.g. {@code 'DR who'}), or just the last name when the owner has no title.
305	     * Derived from the owner's own fields.
306	     */
307	    @Transient
308	    public String getSalutation() {
309	        if (this.title == null || this.title.isBlank()) {
310	            return this.getLastName();
311	        }
312	        return this.title + " " + this.getLastName();
313	    }
314	
315	    /**
316	     * The owner's initials: the upper-cased first letters of the first and last name,
317	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
318	     */
319	    @Transient
320	    public String getInitials() {
321	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
322	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
323	    }
324	
325	    /**
326	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the two-digit fiscal-year
327	     * segment carried by the owner's {@link #getMemberId() member id} (e.g. {@code 'FY26'} for a member
328	     * id whose {@code <FY>} segment is {@code '26'}). The member id bakes in the fiscal year (which
329	     * starts on 1 July) of the business-day-adjusted registration date at creation time, so this reads
330	     * that value back from the member id. {@code null} until the owner has a member id.
331	     */
332	    @Transient
333	    public String getFiscalYear() {
334	        if (this.memberId == null) {
335	            return null;
336	        }
337	        String base = memberIdBase();
338	        int length = base.length();
339	        if (length < MEMBER_ID_FIXED_TAIL) {
340	            return null;
341	        }
342	        return "FY" + base.substring(length - MEMBER_ID_FIXED_TAIL,
343	            length - (MEMBER_ID_HASH8_LENGTH + MEMBER_ID_CHK_LENGTH));
344	    }
345	
346	    /**
347	     * The owner's membership points, a score accumulated from the owner's own fields. It starts at
348	     * 0 and gains: 2 when the owner has an email address; 1 when the owner is unique
349	     * ({@code namesakeCount} is 0); 2 when the owner belongs to a household of 3 or more members
350	     * (the owner together with their pets); and 3 when the owner's tenure spans at least one elapsed
351	     * fiscal year, measured as the difference between the fiscal year of today and the fiscal year of
352	     * {@code registrationDate}. Because a newly created owner has zero elapsed fiscal years of tenure,
353	     * a new owner never earns the tenure points. The score feeds {@link #getMembershipLevel()}.
354	     */
355	    @Transient
356	    public Integer getMembershipPoints() {
357	        int points = 0;
358	        boolean hasEmail = this.email != null && !this.email.isBlank();
359	        if (hasEmail) {
360	            points += 2;
361	        }
362	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
363	        if (unique) {
364	            points += 1;
365	        }
366	        int householdSize = 1 + getPetsInternal().size();
367	        if (householdSize >= 3) {
368	            points += 2;
369	        }
370	        boolean tenured = this.registrationDate != null
371	            && FiscalYear.of(LocalDate.now()) - FiscalYear.of(this.registrationDate) > 0;
372	        if (tenured) {
373	            points += 3;
374	        }
375	        return points;
376	    }
377	
378	    /**
379	     * The owner's numeric membership level, from 1 to 4. By default it is derived from
380	     * {@link #getMembershipPoints()}: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and
381	     * 4 for 6 or more points. When a level has been assigned and stored at creation time (the capped
382	     * level computed against the owner's household), that stored value is returned instead, so the
383	     * level read back for the owner reflects the household ceiling applied when the owner was created.
384	     */
385	    @Transient
386	    public Integer getMembershipLevel() {
387	        if (this.membershipLevel != null) {
388	            return this.membershipLevel;
389	        }
390	        return getDerivedMembershipLevel();
391	    }
392	
393	    /**
394	     * Stores the owner's membership level, overriding the value otherwise derived from the owner's
395	     * membership points. Used at creation time to persist the household-capped level.
396	     */
397	    public void setMembershipLevel(Integer membershipLevel) {
398	        this.membershipLevel = membershipLevel;
399	    }
400	
401	    /**
402	     * The owner's membership level derived purely from {@link #getMembershipPoints()}, before any
403	     * household cap: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more
404	     * points.
405	     */
406	    @Transient
407	    public Integer getDerivedMembershipLevel() {
408	        int points = getMembershipPoints();
409	        if (points >= 6) {
410	            return 4;
411	        }
412	        if (points >= 4) {
413	            return 3;
414	        }
415	        if (points >= 2) {
416	            return 2;
417	        }
418	        return 1;
419	    }
420	
421	    /**
422	     * The owner's locality: the canonical region carried by the {@link #getMemberId() member id}, which
423	     * is its leading {@code <REGION>} segment — everything preceding the two-digit fiscal year, the
424	     * eight-character {@code HASH8} and the single check digit that complete the base member id (e.g.
425	     * {@code 'NSW'} for member id {@code 'NSW261A2B3C4D7'}). The region is the one derived from the
426	     * postcode at creation time and baked into the identity. {@code 'UNKNOWN'} when the owner has no
427	     * member id yet.
428	     */
429	    @Transient
430	    public String getLocality() {
431	        if (this.memberId == null) {
432	            return "UNKNOWN";
433	        }
434	        String base = memberIdBase();
435	        if (base.length() <= MEMBER_ID_FIXED_TAIL) {
436	            return "UNKNOWN";
437	        }
438	        return base.substring(0, base.length() - MEMBER_ID_FIXED_TAIL);
439	    }
440	
441	    /**
442	     * Fixed region-to-timezone lookup mapping each canonical region to its IANA timezone name:
443	     * {@code NSW -> 'Australia/Sydney'}, {@code VIC -> 'Australia/Melbourne'},
444	     * {@code QLD -> 'Australia/Brisbane'}.
445	     */
446	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
447	        "NSW", "Australia/Sydney",
448	        "VIC", "Australia/Melbourne",
449	        "QLD", "Australia/Brisbane");
450	
451	    /**
452	     * The owner's timezone: the IANA name derived from the owner's {@link #getLocality() locality}
453	     * via the fixed region-to-timezone table ({@code NSW -> 'Australia/Sydney'},
454	     * {@code VIC -> 'Australia/Melbourne'}, {@code QLD -> 'Australia/Brisbane'}). {@code null} when
455	     * the locality is not one of these regions.
456	     */
457	    @Transient
458	    public String getTimezone() {
459	        return REGION_TIMEZONE.get(getLocality());
460	    }
461	
462	    /**
463	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
464	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. The
465	     * {@code <TIER>} is {@code 'PREMIUM'} when the owner's {@link #getMembershipLevel() membership
466	     * level} is 3 or more, otherwise {@code 'STANDARD'}. The {@code <AREA>} is {@code 'METRO'} when
467	     * the owner's {@link #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
468	     * {@code 'REGIONAL'}. Derived from the owner's own fields.
469	     */
470	    @Transient
471	    public String getOwnerSegment() {
472	        Integer level = getMembershipLevel();
473	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
474	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
475	        return tier + "_" + area;
476	    }
477	
478	    /**
479	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
480	     * the lower-case hex SHA-256 digest of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}.
481	     * The telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
482	     * owner has none), and the final segment the American Soundex code of the owner's last name. Two
483	     * owners are duplicates only when their whole identity keys are equal; because the telephone is
484	     * part of the key, two owners with the same last name and postcode but different telephones have
485	     * different identity keys and are not hard duplicates.
486	     */
487	    @Transient
488	    public String getIdentityKey() {
489	        String telephonePart = this.telephone == null ? "" : this.telephone;
490	        String emailPart = this.email == null ? "" : this.email;
491	        String soundexPart = soundex(this.getLastName());
492	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
493	    }
494	
495	    /**
496	     * The American Soundex code of the owner's last name, used to group similar-sounding surnames for
497	     * soft (possible-duplicate) matching. Derived from the owner's own last name.
498	     */
499	    @Transient
500	    public String getLastNameSoundex() {
501	        return soundex(this.getLastName());
502	    }
503	
504	    /**
505	     * Computes the American Soundex code of a name: its first letter (upper-cased) followed by three
506	     * digits derived from the remaining consonants, with adjacent duplicate codes (and codes separated
507	     * only by {@code H} or {@code W}) collapsed, then zero-padded and truncated to four characters. A
508	     * {@code null} or letter-free value yields an empty string.
509	     *
510	     * @param value the name to encode
511	     * @return the four-character Soundex code, or an empty string
512	     */
513	    private static String soundex(String value) {
514	        if (value == null) {
515	            return "";
516	        }
517	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
518	        if (letters.isEmpty()) {
519	            return "";
520	        }
521	        StringBuilder code = new StringBuilder();
522	        code.append(letters.charAt(0));
523	        char previousDigit = soundexDigit(letters.charAt(0));
524	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
525	            char c = letters.charAt(i);
526	            char digit = soundexDigit(c);
527	            if (digit != '0' && digit != previousDigit) {
528	                code.append(digit);
529	            }
530	            if (c != 'H' && c != 'W') {
531	                previousDigit = digit;
532	            }
533	        }
534	        while (code.length() < 4) {
535	            code.append('0');
536	        }
537	        return code.toString();
538	    }
539	
540	    /**
541	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for the vowels and the
542	     * letters {@code H}, {@code W} and {@code Y} that carry no Soundex digit.
543	     */
544	    private static char soundexDigit(char c) {
545	        switch (c) {
546	            case 'B': case 'F': case 'P': case 'V':
547	                return '1';
548	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
549	                return '2';
550	            case 'D': case 'T':
551	                return '3';
552	            case 'L':
553	                return '4';
554	            case 'M': case 'N':
555	                return '5';
556	            case 'R':
557	                return '6';
558	            default:
559	                return '0';
560	        }
561	    }
562	
563	    /**
564	     * The owner's preferred contact channel, derived from the owner's own fields:
565	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
566	     */
567	    @Transient
568	    public String getContactPreference() {
569	        boolean hasEmail = this.email != null && !this.email.isBlank();
570	        return hasEmail ? "EMAIL" : "PHONE";
571	    }
572	
573	    /**
574	     * The owner's age band, derived from the owner's own fields: the whole number of years from
575	     * {@code birthDate} to {@code registrationDate} placed into a band — {@code 'MINOR'} when under
576	     * 18, {@code 'ADULT'} when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is measured
577	     * as of the registration date rather than today, so the band is stable over time. {@code null}
578	     * when the owner has no birth date (or no registration date to measure against).
579	     */
580	    @Transient
581	    public String getAgeBand() {
582	        if (this.birthDate == null || this.registrationDate == null) {
583	            return null;
584	        }
585	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
586	        if (age < 18) {
587	            return "MINOR";
588	        }
589	        if (age < 65) {
590	            return "ADULT";
591	        }
592	        return "SENIOR";
593	    }
594	
595	    protected Set<Pet> getPetsInternal() {
596	        if (this.pets == null) {
597	            this.pets = new HashSet<>();
598	        }
599	        return this.pets;
600	    }
601	
602	    protected void setPetsInternal(Set<Pet> pets) {
603	        this.pets = pets;
604	    }
605	
606	    public List<Pet> getPets() {
607	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
608	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
609	        return Collections.unmodifiableList(sortedPets);
610	    }
611	
612	    public void setPets(List<Pet> pets) {
613	        this.pets = new HashSet<>(pets);
614	    }
615	
616	    public void addPet(Pet pet) {
617	        getPetsInternal().add(pet);
618	        pet.setOwner(this);
619	    }
620	
621	    /**
622	     * Return the Pet with the given name, or null if none found for this Owner.
623	     *
624	     * @param name to test
625	     * @return true if pet name is already in use
626	     */
627	    public Pet getPet(String name) {
628	        return getPet(name, false);
629	    }
630	
631	    /**
632	     * Return the Pet with the given name, or null if none found for this Owner.
633	     *
634	     * @param name to test
635	     * @return true if pet name is already in use
636	     */
637	    public Pet getPet(String name, boolean ignoreNew) {
638	        name = name.toLowerCase();
639	        for (Pet pet : getPetsInternal()) {
640	            if (!ignoreNew || !pet.isNew()) {
641	                String compName = pet.getName();
642	                compName = compName.toLowerCase();
643	                if (compName.equals(name)) {
644	                    return pet;
645	                }
646	            }
647	        }
648	        return null;
649	    }
650	
651	    public Pet getPet(Integer petId) {
652	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
653	    }
654	
655	    @Override
656	    public String toString() {
657	        return new ToStringCreator(this)
658	
659	            .append("id", this.getId())
660	            .append("new", this.isNew())
661	            .append("lastName", this.getLastName())
662	            .append("firstName", this.getFirstName())
663	            .append("address", this.address)
664	            .append("city", this.city)
665	            .append("telephone", this.telephone)
666	            .toString();
667	    }
668	}
