259	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
260	    @Override
261	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
262	        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
263	        if (replay != null) {
264	            return replay;
265	        }
266	        validateRequiredFields(ownerFieldsDto);
267	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
268	        LocalDate registrationDate = toBusinessDay(
269	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
270	        rejectDailyLimitReached(registrationDate);
271	        HttpHeaders headers = new HttpHeaders();
272	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
273	        applyAddress(owner, ownerFieldsDto);
274	        rejectCityAtCapacity(owner.getCity());
275	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
276	        owner.setTelephone(telephone);
277	        String email = normalizeEmail(ownerFieldsDto.getEmail());
278	        owner.setEmail(email);
279	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), regionForCity(owner.getCity())));
280	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
281	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
282	        rejectDuplicateIdentity(owner);
283	        applyPossibleDuplicate(owner, sharesHousehold);
284	        owner.setRegistrationDate(registrationDate);
285	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
286	        owner.setMemberId(generateMemberId(owner.getPostcode(), owner.getTelephone(),
287	            owner.getLastName(), owner.getRegistrationDate()));
288	        owner.setMembershipLevel(cappedMembershipLevel(owner));
289	        this.clinicService.saveOwner(owner);
290	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
291	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
292	            owner.getMembershipLevel());
293	        emitOwnerCreatedEvent(owner);
294	        enqueueWelcomeNotification(owner);
295	        rememberIdempotentCreate(idempotencyKey, owner.getId());
296	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
297	        applyBulkSignupWarning(ownerDto);
298	        applyCapacityWarning(ownerDto);
299	        headers.setLocation(UriComponentsBuilder.newInstance()
300	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
301	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
302	    }
