304	    /**
305	     * Serves a repeated create that carries an {@code Idempotency-Key} already seen on an earlier
306	     * successful create. When the key has a remembered owner that still exists, the originally created
307	     * owner is returned with {@code 200 OK} (carrying its {@code Location}) so the retry neither creates
308	     * a duplicate nor re-runs the create rules. A {@code null} or blank key, an unseen key, or a key
309	     * whose owner no longer exists yields {@code null}, signalling the caller to perform a normal create.
310	     *
311	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
312	     * @return the originally created owner as a {@code 200 OK} response, or {@code null} to create normally
313	     */
314	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
315	        if (isBlank(idempotencyKey)) {
316	            return null;
317	        }
318	        Integer ownerId = idempotentCreateOwnerIds.get(idempotencyKey);
319	        if (ownerId == null) {
320	            return null;
321	        }
322	        Owner owner = this.clinicService.findOwnerById(ownerId);
323	        if (owner == null) {
324	            return null;
325	        }
326	        HttpHeaders headers = new HttpHeaders();
327	        headers.setLocation(UriComponentsBuilder.newInstance()
328	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
329	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
330	        applyBulkSignupWarning(ownerDto);
331	        applyCapacityWarning(ownerDto);
332	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.OK);
333	    }
334	
335	    /**
336	     * Remembers the owner just created under its request's {@code Idempotency-Key}, so a later create
337	     * repeating that key is served the same owner ({@link #replayIdempotentCreate}). A {@code null} or
338	     * blank key is ignored, leaving that create non-idempotent.
339	     *
340	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
341	     * @param ownerId        the id of the owner that was just created
342	     */
343	    private void rememberIdempotentCreate(String idempotencyKey, Integer ownerId) {
344	        if (!isBlank(idempotencyKey)) {
345	            idempotentCreateOwnerIds.put(idempotencyKey, ownerId);
346	        }
347	    }
