349	    /**
350	     * Emits the immutable structured {@code OWNER_CREATED} event for a freshly created owner on the
351	     * {@code AUDIT} logger, serialized as a JSON object {@code {seq, ownerId, memberId,
352	     * membershipLevel, event}}. The {@code seq} is drawn from {@link #OWNER_CREATED_SEQ}, advancing by
353	     * one per create so the events carry a total order. The {@code memberId} field carries the owner's
354	     * current primary identifier ({@link #primaryIdentifier}) — the unified member id.
355	     *
356	     * @param owner the owner that was just created and saved
357	     */
358	    private void emitOwnerCreatedEvent(Owner owner) {
359	        OwnerCreatedEvent event = new OwnerCreatedEvent(
360	            OWNER_CREATED_SEQ.incrementAndGet(),
361	            owner.getId(),
362	            primaryIdentifier(owner),
363	            owner.getMembershipLevel());
364	        AUDIT.info("{}", AUDIT_MAPPER.writeValueAsString(event));
365	    }
366	
367	    /**
368	     * Enqueues a welcome notification for a freshly created owner by emitting a single line on the
369	     * {@code NOTIFY} logger carrying the new owner's id and member id.
370	     *
371	     * @param owner the owner that was just created and saved
372	     */
373	    private void enqueueWelcomeNotification(Owner owner) {
374	        NOTIFY.info("Welcome notification: ownerId={} memberId={}",
375	            owner.getId(), primaryIdentifier(owner));
376	    }
