378	    /**
379	     * Returns the owner's current primary identifier — the single value that externally names the
380	     * owner and is carried by the structured audit event. That is the unified {@code memberId}; this
381	     * is the one place to change should a later evolution replace it, so every consumer of the primary
382	     * identifier follows automatically.
383	     *
384	     * @param owner the owner whose primary identifier is wanted
385	     * @return the owner's current primary identifier
386	     */
387	    private String primaryIdentifier(Owner owner) {
388	        return owner.getMemberId();
389	    }
