391	    /**
392	     * Immutable structured audit event emitted on a successful owner create. Serialized to JSON on the
393	     * {@code AUDIT} logger, its component order fixes the field order {@code {seq, ownerId, memberId,
394	     * membershipLevel, event}}. The {@code event} discriminator is always {@code 'OWNER_CREATED'}. The
395	     * {@code memberId} component holds the owner's current primary identifier
396	     * ({@link #primaryIdentifier}) — the unified member id.
397	     *
398	     * @param seq             monotonically increasing sequence across all creates
399	     * @param ownerId         the new owner's id
400	     * @param memberId        the owner's current primary identifier
401	     * @param membershipLevel the owner's stored membership level
402	     */
403	    private record OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel,
404	                                     String event) {
405	        private OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel) {
406	            this(seq, ownerId, memberId, membershipLevel, "OWNER_CREATED");
407	        }
408	    }
