505	    /**
506	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
507	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
508	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
509	     *
510	     * @param ownerFieldsDto the submitted owner fields
511	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
512	     *                                     name of every offending field
513	     */
514	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
515	        List<String> missingFields = new ArrayList<>();
516	        if (isBlank(ownerFieldsDto.getFirstName())) {
517	            missingFields.add("firstName");
518	        }
519	        if (isBlank(ownerFieldsDto.getLastName())) {
520	            missingFields.add("lastName");
521	        }
522	        if (!hasAddress(ownerFieldsDto)) {
523	            missingFields.add("address");
524	        }
525	        if (isBlank(ownerFieldsDto.getCity())) {
526	            missingFields.add("city");
527	        }
528	        if (isBlank(ownerFieldsDto.getTelephone())) {
529	            missingFields.add("telephone");
530	        }
531	        if (!missingFields.isEmpty()) {
532	            throw new InvalidOwnerFieldsException(missingFields);
533	        }
534	    }
535	
536	    private boolean isBlank(String value) {
537	        return value == null || value.isBlank();
538	    }
