540	    /**
541	     * Reports whether an existing owner has not been soft-deleted. The create endpoint's duplicate
542	     * and identity checks consider only live owners, so an owner flagged {@code deleted} no longer
543	     * blocks a new owner that would otherwise match it.
544	     *
545	     * @param owner an existing owner
546	     * @return {@code true} unless the owner is flagged deleted
547	     */
548	    private boolean isNotDeleted(Owner owner) {
549	        return !Boolean.TRUE.equals(owner.getDeleted());
550	    }
551	
552	    /**
553	     * Rejects a supplied {@code registrationDate} that is later than the current server date. A
554	     * {@code null} value means the field was omitted and the registration date will default to the
555	     * server date, so there is nothing to reject. A supplied date on or before today is accepted; the
556	     * raw supplied value is compared against the server date before any business-day adjustment.
557	     *
558	     * @param registrationDate the registration date supplied by the client, or {@code null} if omitted
559	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server date, yielding a
560	     *                                     400 Bad Request response
561	     */
562	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
563	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
564	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
565	        }
566	    }
567	
568	    /**
569	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
570	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
571	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
572	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
573	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
574	     * The returned value is stored and returned unchanged.
575	     *
576	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
577	     * @param region   the owner's region derived from its city
578	     * @return the postcode to store, or {@code null} if none was supplied
579	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
580	     *                                     out of range for the city's region, yielding a 400 response
581	     */
582	    private String validatePostcode(String postcode, String region) {
583	        if (postcode == null) {
584	            return null;
585	        }
586	        if (!postcode.matches("[0-9]{4}")) {
587	            throw new InvalidOwnerFieldsException(List.of("postcode"));
588	        }
589	        int[] range = REGION_POSTCODES.get(region);
590	        if (range != null) {
591	            int value = Integer.parseInt(postcode);
592	            if (value < range[0] || value > range[1]) {
593	                throw new InvalidOwnerFieldsException(List.of("postcode"));
594	            }
595	        }
596	        return postcode;
597	    }
