599	    /**
600	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
601	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
602	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
603	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
604	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
605	     *
606	     * @param telephone the raw telephone value submitted by the client
607	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
608	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
609	     *                                     400 response
610	     */
611	    private String normalizeTelephone(String telephone) {
612	        String e164 = toE164(telephone);
613	        if (e164 == null) {
614	            throw new InvalidOwnerFieldsException(List.of("telephone"));
615	        }
616	        return e164;
617	    }
