619	    /**
620	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
621	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
622	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
623	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
624	     * and when the supplied country code is one with a known national-number length
625	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
626	     * number must have exactly that many digits.
627	     *
628	     * @param telephone the raw telephone value, possibly {@code null}
629	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
630	     */
631	    private String toE164(String telephone) {
632	        if (telephone == null) {
633	            return null;
634	        }
635	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
636	        boolean hasPlus = cleaned.startsWith("+");
637	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
638	        String nationalSignificant = hasPlus
639	            ? digits
640	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
641	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
642	            return null;
643	        }
644	        if (!hasValidNationalNumberLength(nationalSignificant)) {
645	            return null;
646	        }
647	        return "+" + nationalSignificant;
648	    }
649	
650	    /**
651	     * Checks the national-number length of an E.164 number (country code plus national significant
652	     * digits, no leading {@code '+'}) against the per-country requirement in
653	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
654	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
655	     * country code is not listed carries no per-country length requirement and is accepted.
656	     *
657	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
658	     *                            leading {@code '+'}
659	     * @return {@code true} if the national-number length is correct for the country code, or the
660	     *         country code has no listed requirement; {@code false} otherwise
661	     */
662	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
663	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
664	            .filter(nationalSignificant::startsWith)
665	            .max(Comparator.comparingInt(String::length))
666	            .orElse(null);
667	        if (countryCode == null) {
668	            return true;
669	        }
670	        int nationalLength = nationalSignificant.length() - countryCode.length();
671	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
672	    }
