720	    /**
721	     * Builds the owner's {@code memberId}, formatted {@code '<REGION><FY><HASH8><CHK>'} with no
722	     * separators, unifying the former customer code and membership number into a single value.
723	     * {@code REGION} is the region code derived from the owner's postcode ({@link #regionForPostcode},
724	     * {@code 'UNKNOWN'} when the postcode is absent or in no known range); {@code FY} is the two-digit
725	     * fiscal year (which starts on 1 July) of the business-day-adjusted {@code registrationDate};
726	     * {@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the owner's
727	     * normalized telephone followed by the last name (the same segment used by the region-and-hash
728	     * identity); and {@code CHK} is a single Luhn check digit computed over the digits of
729	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW261A2B3C4D7'}). The identity carries no sequence
730	     * number, so the same postcode region, fiscal year, telephone and last name always yield the same
731	     * member id.
732	     *
733	     * <p>If the computed member id collides with an existing owner's {@code memberId}, it is
734	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
735	     * unique, so distinct owners always receive distinct member ids.
736	     *
737	     * @param postcode         the owner's validated postcode, or {@code null} if none was supplied
738	     * @param telephone        the owner's normalized (E.164) telephone
739	     * @param lastName         the owner's last name
740	     * @param registrationDate the owner's business-day-adjusted registration date
741	     * @return the formatted, de-duplicated member id
742	     */
743	    private String generateMemberId(String postcode, String telephone, String lastName, LocalDate registrationDate) {
744	        String region = regionForPostcode(postcode);
745	        String fy = String.format("%02d", FiscalYear.of(registrationDate) % 100);
746	        String hash8 = hashHex(telephone + lastName, 8);
747	        String prefix = region + fy + hash8;
748	        String baseId = prefix + luhnCheckDigit(prefix);
749	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
750	            .map(Owner::getMemberId)
751	            .filter(Objects::nonNull)
752	            .collect(Collectors.toSet());
753	        if (!existingIds.contains(baseId)) {
754	            return baseId;
755	        }
756	        int n = 2;
757	        while (existingIds.contains(baseId + "-" + n)) {
758	            n++;
759	        }
760	        return baseId + "-" + n;
761	    }
