763	    /**
764	     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value}. The standard
765	     * Luhn algorithm runs over the digits from right to left, doubling every second digit (subtracting
766	     * 9 when a doubled value exceeds 9); non-digit characters are skipped. This is the {@code <CHK>}
767	     * segment of a {@code memberId}, computed over the digits of its {@code <REGION><FY><HASH8>} prefix.
768	     *
769	     * @param value the value whose digits the check digit is computed over
770	     * @return the Luhn check digit, 0 to 9
771	     */
772	    private int luhnCheckDigit(String value) {
773	        int sum = 0;
774	        boolean dbl = true;
775	        for (int i = value.length() - 1; i >= 0; i--) {
776	            char c = value.charAt(i);
777	            if (c < '0' || c > '9') {
778	                continue;
779	            }
780	            int d = c - '0';
781	            if (dbl) {
782	                d *= 2;
783	                if (d > 9) {
784	                    d -= 9;
785	                }
786	            }
787	            sum += d;
788	            dbl = !dbl;
789	        }
790	        return (10 - (sum % 10)) % 10;
791	    }
