793	    /**
794	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
795	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
796	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
797	     * {@code <REGION>} segment baked into the {@code memberId}.
798	     *
799	     * @param postcode the owner's postcode, or {@code null}
800	     * @return the region code, or {@code 'UNKNOWN'}
801	     */
802	    private String regionForPostcode(String postcode) {
803	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
804	            return "UNKNOWN";
805	        }
806	        int value = Integer.parseInt(postcode);
807	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
808	            int[] range = entry.getValue();
809	            if (value >= range[0] && value <= range[1]) {
810	                return entry.getKey();
811	            }
812	        }
813	        return "UNKNOWN";
814	    }
