942	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
943	     */
944	    private LocalDate toBusinessDay(LocalDate date) {
945	        LocalDate adjusted = date;
946	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
947	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY
948	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
949	            adjusted = adjusted.plusDays(1);
950	        }
951	        return adjusted;
952	    }
