1023	    /**
1024	     * Caps the membership level of the owner being created so it cannot exceed one above the current
1025	     * maximum membership level among its existing household members. A household member is a live (not
1026	     * soft-deleted) owner carrying the same computed {@code householdId}. The owner's own derived level
1027	     * ({@link Owner#getDerivedMembershipLevel()}) is returned capped at that maximum plus one; when the
1028	     * owner belongs to no household, or no existing household member is found, no cap applies and the
1029	     * derived level is returned unchanged. The owner being created has not been saved yet, so it is
1030	     * never considered its own household member.
1031	     *
1032	     * @param owner the owner being created, with its household id and level-affecting fields set
1033	     * @return the membership level to store, capped to the household ceiling where one exists
1034	     */
1035	    private Integer cappedMembershipLevel(Owner owner) {
1036	        int derivedLevel = owner.getDerivedMembershipLevel();
1037	        String householdId = owner.getHouseholdId();
1038	        if (householdId == null || householdId.isBlank()) {
1039	            return derivedLevel;
1040	        }
1041	        OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
1042	            .filter(this::isNotDeleted)
1043	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1044	            .mapToInt(Owner::getMembershipLevel)
1045	            .max();
1046	        if (maxHouseholdLevel.isEmpty()) {
1047	            return derivedLevel;
1048	        }
1049	        return Math.min(derivedLevel, maxHouseholdLevel.getAsInt() + 1);
1050	    }
