1053	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
1054	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
1055	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
1056	     * shares both automatically shares the same household id, so the household is keyed on
1057	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
1058	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
1059	     * still land in the same household.
1060	     *
1061	     * @param lastName the owner's last name
1062	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
1063	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
1064	     *         to no postcode-keyed household
1065	     */
1066	    private String computeHouseholdId(String lastName, String postcode) {
1067	        if (postcode == null) {
1068	            return null;
1069	        }
1070	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
1071	    }
