1073	    /**
1074	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
1075	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
1076	     * the result is lower-cased.
1077	     *
1078	     * @param value the value to normalize, possibly {@code null}
1079	     * @return the normalized value, or an empty string if {@code value} is {@code null}
1080	     */
1081	    private String normalizeForComparison(String value) {
1082	        if (value == null) {
1083	            return "";
1084	        }
1085	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1086	    }
1087	
1088	    /**
1089	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
1090	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
1091	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
1092	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
1093	     * This normalized value is what gets stored and returned.
1094	     *
1095	     * @param address the raw address value submitted by the client, possibly {@code null}
1096	     * @return the normalized address, or an empty string if {@code address} is {@code null}
1097	     */
1098	    private String normalizeAddress(String address) {
1099	        if (address == null) {
1100	            return "";
1101	        }
1102	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
1103	        if (collapsed.isEmpty()) {
1104	            return collapsed;
1105	        }
1106	        String[] tokens = collapsed.split(" ");
1107	        StringBuilder normalized = new StringBuilder(collapsed.length());
1108	        for (int i = 0; i < tokens.length; i++) {
1109	            if (i > 0) {
1110	                normalized.append(' ');
1111	            }
1112	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1113	        }
1114	        return normalized.toString();
1115	    }
1116	
1117	    /**
1118	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
1119	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
1120	     * preferred when present, but either satisfies the address requirement, keeping the create
1121	     * contract backward-compatible with earlier flat-address-only owners.
1122	     *
1123	     * @param ownerFieldsDto the submitted owner fields
1124	     * @return {@code true} if an address is supplied in either form
1125	     */
1126	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
1127	        return !isBlank(ownerFieldsDto.getAddressLine1())
1128	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
1129	    }
1130	
1131	    /**
1132	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
1133	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
1134	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
1135	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
1136	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
1137	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
1138	     * working while letting everything that reads the address use the composed, normalized value.
1139	     *
1140	     * @param owner          the owner being created
1141	     * @param ownerFieldsDto the submitted owner fields
1142	     */
1143	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
1144	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
1145	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
1146	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
1147	                ? null
1148	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
1149	            owner.setAddressLine1(line1);
1150	            owner.setAddressLine2(line2);
1151	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
1152	        } else {
1153	            owner.setAddressLine1(null);
1154	            owner.setAddressLine2(null);
1155	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
1156	        }
1157	    }
1158	}
